export type PhotoResolution = "low" | "medium" | "high";
export type AudioQuality = "low" | "medium" | "high";
export type AppSettings = {
  countdownSeconds: number;
  photoResolution: PhotoResolution;
  audioQuality: AudioQuality;
};
const DEFAULT_SETTINGS: AppSettings = {
  countdownSeconds: 3,
  photoResolution: "high",
  audioQuality: "high",
};

const PHOTO_LEVELS = ["low", "medium", "high"];
const AUDIO_LEVELS = ["low", "medium", "high"];

onValueChange={(value) => {
  const resolution = PHOTO_LEVELS[
    Math.round(value)
  ];
  if (resolution) {
    updateSettings({ photoResolution: resolution });
  }
}}
updateSettings({
  countdownSeconds: Math.round(value),
});

const nextSettings = getStoredSettings({
  ...settingsRef.current,
  ...updates,
});
changedBeforeLoadRef.current = true;
settingsRef.current = nextSettings;
setSettings(nextSettings);

void AsyncStorage.setItem(
  STORAGE_KEY,
  JSON.stringify(nextSettings)
).catch((error) => {
  console.warn("Unable to save settings:", error);
});

let current = settings.countdownSeconds;
setCountdown(current);

countdownTimerRef.current = setInterval(() => {
  current -= 1;

  if (current > 0) {
    setCountdown(current);
    return;
  }

  setCountdown(null);
  void takePhoto();
}, 1000);

if (!cameraPermission?.granted ||
    !isCameraReady ||
    !isFocused ||
    !isHydrated ||
    appState !== "active") {
  return;
}
Accelerometer.setUpdateInterval(100);
if (force > 2.2 &&
    now - lastShakeTime > 1000) {
  lastShakeTime = now;
  startShakeCountdown();
}

const fourByThreeSizes = numericSizes.filter(size =>
  Math.abs(size.ratio - 4 / 3) < 0.03
);

const candidates = fourByThreeSizes.length >= 3
  ? fourByThreeSizes
  : numericSizes;

candidates.sort((a, b) => a.pixels - b.pixels);

const index = resolution === "low" ? 0
  : resolution === "medium"
    ? Math.floor((candidates.length - 1) / 2)
    : candidates.length - 1;

return candidates[index]?.value;

const cameraKey =
  `${facing}:${selectedPictureSize ?? "detect"}`;

{isFocused && appState === "active" && (
  <CameraView
    facing={facing}
    key={cameraKey}
    onCameraReady={handleCameraReady}
    pictureSize={selectedPictureSize}
    ratio={selectedPictureSize ? undefined : "4:3"}
    ref={setCameraInstance}
    style={styles.camera}
  />
)}

const LOW_QUALITY_RECORDING_OPTIONS = {
  ...RecordingPresets.HIGH_QUALITY,
  bitRate: 64000,
  ios: { audioQuality: AudioQuality.LOW },
  web: { bitsPerSecond: 64000 },
};

const MEDIUM_QUALITY_RECORDING_OPTIONS = {
  ...RecordingPresets.HIGH_QUALITY,
  bitRate: 96000,
  ios: { audioQuality: AudioQuality.MEDIUM },
  web: { bitsPerSecond: 96000 },
};

type RecorderPhase = "idle" | "starting"
  | "recording" | "stopping";

if (recorderPhaseRef.current !== "recording") {
  return;
}
changeRecorderPhase("stopping");

await recorder.stop();
const uri = recorder.uri;

if (uri) {
  setRecordingUri(uri);
}

await setAudioModeAsync({ allowsRecording: false });
